                post_hook={
                    "sql": "create or replace table datalake_db.kaya.dwh_kaya_daily_offtake_report as With base as( select DATE::date as DATE ,ASIN ,PLATFORM_NAME ,upper(coalesce(fsm1.PRODUCT_TITLE, fsm.PRODUCT_TITLE,od.PRODUCT_TITLE)) PRODUCT_TITLE ,od.EAN ,SHIPPED_UNIT ,MATERIAL_CODE ,MATERIAL_GROUP_CODE ,MATERIAL_GROUP_DESC ,UOM_REPORTING ,VOL_PER_UNIT ,VOL_IN_LIT ,VOL_IN_RUM ,INDEXRATE ,INDEXBPM ,CATEGORY ,od.date::date as month ,indexbpm as ACTUAL_NUMERATOR ,upper(coalesce(fsm1.SUB_CATEGORY, fsm.SUB_CATEGORY)) SUB_CATEGORY ,upper(coalesce(fsm1.PRODUCT_NAME, fsm.PRODUCT_NAME)) PRODUCT_NAME ,case when ifnull(upper(\"Priority Product\"),\'\') = \'YES\' then \'YES\' else \'NO\' end as Priority_Product from PRD_DB_SHR.PUBLIC.DWH_IND_ECOMM_OFFTAKE_DAILY od left join ( select * from datalake_db.kaya.trn_kaya_sku_mapping qualify row_number() over(partition by EAN order by 1) = 1 )sm on od.ean = sm.ean left join ( select * from datalake_db.kaya.Final_SKU_master qualify row_number() over(partition by trim(upper(ean)) order by 1) = 1 )fsm on od.ean = fsm.ean left join ( select * from datalake_db.kaya.Final_SKU_master qualify row_number() over(partition by trim(upper(marketplace_SKU)) order by 1) = 1 )fsm1 on upper(od.asin) = upper(fsm1.marketplace_SKU) where upper(material_group_code) in (\'KAYA_GM\' ,\'KAYA_ML\') ), Months as ( select last_day(dateadd(month,1,month)) Date, PLATFORM_NAME Channel, sum(ifnull(INDEXBPM,0)) month_INDEXBPM from Base group by 1,2 ) select bs.*, div0(ifnull(month_INDEXBPM,0),count(*) over(partition by last_day(bs.month), lower(bs.PLATFORM_NAME))) as Last_Month_INDEXBPM from Base bs left join Months ms on last_day(bs.month) = ms.date and lower(bs.PLATFORM_NAME) = lower(ms.Channel) ; CREATE OR REPLACE TABLE datalake_db.kaya.dwh_kaya_ecom_PandL AS WITH MT_ECOM_NR as ( SELECT inv_date AS date, channel_name, case when lower(sub_channel_name) like \'%flipkart%\' then \'FLIPKART\' when lower(sub_channel_name) like \'%grofers%\' then \'BLINKIT\' when lower(sub_channel_name) like \'%innovative retail%\' then \'BIG BASKET\' when lower(sub_channel_name) like \'%kiranakart tech%\' then \'ZEPTO\' when lower(sub_channel_name) like \'%nykaa%\' then \'NYKAA\' when upper(sub_channel_name) like \'%RK WORLDINFOCOM%\' then \'AMAZON\' when upper(sub_channel_name) like \'%SCOOTSY LOGISTICS%\' then \'SWIGGY\' else upper(sub_channel_name) end as new_Channel ,ifnull(SUM(quantity * mrp),0) * 0.38 AS NR FROM prd_db_shr.public.TRN_PRIMARY_SALES_INVOICES_DETAILED a LEFT JOIN datalake_db_shr.public.TRN_MST_CUSTOMER_PWBI b ON a.customer = b.customer_code AND b.company_code = \'MIL\' AND b.latest_record_ind = 1 LEFT JOIN datalake_db_shr.public.TRN_MST_MATERIAL_PWBI c ON a.sku_code = c.material_code AND c.company_code = \'MIL\' AND c.latest_record_ind = 1 WHERE b.sub_channel_group = \'B2C\' AND b.channel_name in (\'MT\',\'E-Commerce\') AND c.material_group_code IN (\'KAYA_ML\', \'KAYA_GM\') GROUP BY 1,2,3 order by 1 desc ), DTC As ( select order_date::date as order_timestamp, \'1.MRP Sales\' AS Metric, \'DTC\' as marketplace, sum(ifnull(mrp_sales,0)) as Actual_Numerator, NULL AS Actual_Denominator from datalake_db.kaya.dwh_unicommerce_fact_items where upper(courierstatus) not like \'%DELIVERED%\' and marketplace = \'KAYASCIENCE_SHOPIFY\' and not((product_name) in (\'sling bag\',\'Kaya Gift Box\',\'Keychain\',\'FestiveGWPBoxWithoutHB\',\'vanitybox\',\'kaya Science Gift Pouch\')) group by 1 UNION ALL select order_date::date as Date, \'2.NR Sales\' AS Metric, \'DTC\' as marketplace, sum((ifnull(selling_price,0) - ifnull(selling_price*18/118 ,0)) * 0.975) as Actual_Numerator, NULL AS Actual_Denominator from datalake_db.kaya.dwh_unicommerce_fact_items where courierstatus = \'DELIVERED\' and marketplace = \'KAYASCIENCE_SHOPIFY\' and not((product_name) in (\'sling bag\',\'Kaya Gift Box\',\'Keychain\',\'FestiveGWPBoxWithoutHB\',\'vanitybox\',\'kaya Science Gift Pouch\')) group by 1 UNION ALL SELECT order_timestamp , \'3.Gross Contribution\' AS Metric, \'DTC\' as marketplace, SUM(IFNULL(gc, 0)) AS Actual_Numerator, NULL AS Actual_Denominator FROM datalake_db.kaya.dwh_gross_contribution_Kaya GROUP BY 1, 2 UNION ALL SELECT order_timestamp , \'4.ASP\' AS Metric, \'DTC\' as marketplace, null AS Actual_Numerator, NULL AS Actual_Denominator FROM datalake_db.kaya.dwh_gross_contribution_Kaya GROUP BY 1, 2 UNION ALL SELECT order_timestamp , \'5.Net Contribution\' AS Metric, \'DTC\' as marketplace, SUM(IFNULL(gc, 0) - ifnull(spend,0)) AS Actual_Numerator, NULL AS Actual_Denominator FROM datalake_db.kaya.dwh_gross_contribution_Kaya GROUP BY 1, 2 UNION ALL SELECT order_timestamp, \'6.GC%\' AS Metric, \'DTC\' as marketplace, SUM(IFNULL(gc, 0)) AS Actual_Numerator, SUM(IFNULL(nr, 0)) AS Actual_Denominator FROM datalake_db.kaya.dwh_gross_contribution_Kaya GROUP BY 1, 2 UNION ALL SELECT order_timestamp, \'7.ASP%\' AS Metric, \'DTC\' as marketplace, null AS Actual_Numerator, SUM(IFNULL(nr, 0)) AS Actual_Denominator FROM datalake_db.kaya.dwh_gross_contribution_Kaya GROUP BY 1, 2 UNION ALL SELECT order_timestamp, \'8.NC%\' AS Metric, \'DTC\' as marketplace, SUM(IFNULL(gc, 0) - ifnull(spend,0)) AS Actual_Numerator, SUM(IFNULL(nr, 0)) AS Actual_Denominator FROM datalake_db.kaya.dwh_gross_contribution_Kaya GROUP BY 1, 2 ), all_channels AS ( SELECT month_date, \'1.MRP Sales\' AS Metric, SUM(IFNULL(value, 0)) AS Actual_Numerator, NULL AS Actual_Denominator FROM PRD_DB_SHR.PUBLIC.VW_IND_BIZFIN_122_COST_STRUCTURE_MARKETING WHERE material_group_code IN (\'KAYA_GM\', \'Kaya_ML\') AND UPPER(VALUE_TYPE_DESC) = \'PBT\' AND UPPER(TIME_VARIANT_CODE) = \'MONTH\' GROUP BY 1, 2 UNION ALL SELECT month_date, \'2.NR Sales\' AS Metric, SUM(IFNULL(value, 0)) AS Actual_Numerator, NULL AS Actual_Denominator FROM PRD_DB_SHR.PUBLIC.VW_IND_BIZFIN_122_COST_STRUCTURE_MARKETING WHERE upper(material_group_code) IN (\'KAYA_GM\', \'KAYA_ML\') AND UPPER(VALUE_TYPE_DESC) = \'NR\' AND UPPER(TIME_VARIANT_CODE) = \'MONTH\' GROUP BY 1, 2 UNION ALL SELECT month_date, \'3.Gross Contribution\' AS Metric, SUM(IFNULL(value, 0)) AS Actual_Numerator, NULL AS Actual_Denominator FROM PRD_DB_SHR.PUBLIC.VW_IND_BIZFIN_122_COST_STRUCTURE_MARKETING WHERE material_group_code IN (\'KAYA_GM\', \'Kaya_ML\') AND UPPER(VALUE_TYPE_DESC) = \'GC\' AND UPPER(TIME_VARIANT_CODE) = \'MONTH\' GROUP BY 1, 2 UNION ALL SELECT month_date, \'4.ASP\' AS Metric, SUM(IFNULL(value, 0)) AS Actual_Numerator, NULL AS Actual_Denominator FROM PRD_DB_SHR.PUBLIC.VW_IND_BIZFIN_122_COST_STRUCTURE_MARKETING WHERE material_group_code IN (\'KAYA_GM\', \'Kaya_ML\') AND UPPER(VALUE_TYPE_DESC) = \'ASP\' AND UPPER(TIME_VARIANT_CODE) = \'MONTH\' GROUP BY 1, 2 UNION ALL SELECT month_date, \'5.Net Contribution\' AS Metric, SUM(IFNULL(value, 0)) AS Actual_Numerator, NULL AS Actual_Denominator FROM PRD_DB_SHR.PUBLIC.VW_IND_BIZFIN_122_COST_STRUCTURE_MARKETING WHERE material_group_code IN (\'KAYA_GM\', \'Kaya_ML\') AND UPPER(VALUE_TYPE_DESC) = \'NC\' AND UPPER(TIME_VARIANT_CODE) = \'MONTH\' GROUP BY 1, 2 UNION ALL SELECT month_date, \'6.GC%\' AS Metric, SUM(CASE WHEN UPPER(VALUE_TYPE_DESC) = \'GC\' THEN IFNULL(value, 0) ELSE 0 END) AS Actual_Numerator, SUM(CASE WHEN UPPER(VALUE_TYPE_DESC) = \'NR\' THEN IFNULL(value, 0) ELSE 0 END) AS Actual_Denominator FROM PRD_DB_SHR.PUBLIC.VW_IND_BIZFIN_122_COST_STRUCTURE_MARKETING WHERE material_group_code IN (\'KAYA_GM\', \'Kaya_ML\') AND UPPER(VALUE_TYPE_DESC) IN (\'NR\', \'GC\') AND UPPER(TIME_VARIANT_CODE) = \'MONTH\' GROUP BY 1, 2 UNION ALL SELECT month_date, \'7.ASP%\' AS Metric, SUM(CASE WHEN UPPER(VALUE_TYPE_DESC) = \'ASP\' THEN IFNULL(value, 0) ELSE 0 END) AS Actual_Numerator, SUM(CASE WHEN UPPER(VALUE_TYPE_DESC) = \'NR\' THEN IFNULL(value, 0) ELSE 0 END) AS Actual_Denominator FROM PRD_DB_SHR.PUBLIC.VW_IND_BIZFIN_122_COST_STRUCTURE_MARKETING WHERE material_group_code IN (\'KAYA_GM\', \'Kaya_ML\') AND UPPER(VALUE_TYPE_DESC) IN (\'NR\', \'ASP\') AND UPPER(TIME_VARIANT_CODE) = \'MONTH\' GROUP BY 1, 2 UNION ALL SELECT month_date, \'8.NC%\' AS Metric, SUM(CASE WHEN UPPER(VALUE_TYPE_DESC) = \'NC\' THEN IFNULL(value, 0) ELSE 0 END) AS Actual_Numerator, SUM(CASE WHEN UPPER(VALUE_TYPE_DESC) = \'NR\' THEN IFNULL(value, 0) ELSE 0 END) AS Actual_Denominator FROM PRD_DB_SHR.PUBLIC.VW_IND_BIZFIN_122_COST_STRUCTURE_MARKETING WHERE material_group_code IN (\'KAYA_GM\', \'Kaya_ML\') AND UPPER(VALUE_TYPE_DESC) IN (\'NR\', \'NC\') AND UPPER(TIME_VARIANT_CODE) = \'MONTH\' GROUP BY 1, 2 ), ACTUALS as ( select month_date, \'ECOM\' as Final_marketplace, \'ECOM+MT\' as marketplace, \'Ecom Total\' Net_Realization, Metric, \'ALL\' as channel, \'ALL\' TYPE, Actual_Numerator, Actual_Denominator, null as tertiary from all_channels union all select order_timestamp, \'DTC\' as Final_marketplace, marketplace, \'DTC\' Net_Realization, Metric, \'DTC\' as channel, \'ALL\' TYEP, Actual_Numerator, Actual_Denominator, null as tertiary from DTC union all select date, \'Modern Trade\' as Final_marketplace, \'ECOM+MT\' as marketplace, \'Modern Trade Total\' Net_Realization, \'2.NR Sales\' Metric, new_Channel, \'NR\' TYEP, nr/100000 Actual_Numerator, null Actual_Denominator, null as tertiary from MT_ECOM_NR where channel_name = \'MT\' union all select date, \'ECOM\' as Final_marketplace, \'ECOM+MT\' as marketplace, \'Ecom Total\' Net_Realization, \'2.NR Sales\' Metric, new_Channel, \'NR\' TYEP, sum(ifnull(nr,0))/100000 as Actual_Numerator, null as Actual_Denominator, null as tertiary from MT_ECOM_NR where channel_name = \'E-Commerce\' group by 1,2,3,4,5,6 UNION ALL select order_date::date as Date, \'DTC\' as Final_marketplace, \'DTC\' as marketplace, \'DTC Total\' Net_Realization, \'2.NR Sales\' AS Metric, \'DTC\' as channel, \'NR\' TYEP, sum((ifnull(selling_price,0) - ifnull(selling_price*18/118 ,0)) * 0.975)/100000 as Actual_Numerator, NULL AS Actual_Denominator, null as tertiary from datalake_db.kaya.dwh_unicommerce_fact_items where courierstatus = \'DELIVERED\' and marketplace = \'KAYASCIENCE_SHOPIFY\' and not((product_name) in (\'sling bag\',\'Kaya Gift Box\',\'Keychain\',\'FestiveGWPBoxWithoutHB\',\'vanitybox\',\'kaya Science Gift Pouch\')) group by 1 UNION ALL select date::date as Date ,\'ECOM\' as Final_marketplace, \'ECOM+MT\' as marketplace, \'Primary Ecom Total\' Net_Realization, \'2.NR Sales\' Metric, upper(PLATFORM_NAME) as new_Channel, \'NR\' TYEP, null as Actual_Numerator, null as Actual_Denominator, sum(ifnull(indexbpm,0)) tertiary from datalake_db.kaya.dwh_kaya_daily_offtake_report group by 1,2,3,4,5,6 UNION ALL select order_date::date as Date, \'DTC\' as Final_marketplace, \'DTC\' as marketplace, \'Primary DTC Total\' Net_Realization, \'2.NR Sales\' AS Metric, \'DTC\' as channel, \'NR\' TYEP, null as Actual_Numerator, NULL AS Actual_Denominator, sum((ifnull(selling_price,0))) /100000 as tertiary from datalake_db.kaya.dwh_unicommerce_fact_items where courierstatus = \'DELIVERED\' and marketplace = \'KAYASCIENCE_SHOPIFY\' and not((product_name) in (\'sling bag\',\'Kaya Gift Box\',\'Keychain\',\'FestiveGWPBoxWithoutHB\',\'vanitybox\',\'kaya Science Gift Pouch\')) group by 1 ), Targets AS ( WITH monthly_targets AS ( SELECT TO_DATE(month, \'DD-MM-YYYY\') AS month_start, LAST_DAY(TO_DATE(month, \'DD-MM-YYYY\')) AS month_end, CASE WHEN LOWER(metric) = \'nr\' THEN \'2.NR Sales\' ELSE NULL END AS metric, upper(channel) AS marketplace, upper(chain) Chain , TRY_CAST(target AS FLOAT) AS target_value FROM datalake_db.kaya.trn_pandl_targets WHERE target IS NOT NULL ), day_generator AS ( SELECT SEQ4() AS day_offset FROM TABLE(GENERATOR(ROWCOUNT => 31)) ), expanded_days AS ( SELECT mt.month_start, mt.month_end, mt.metric, mt.Chain, mt.marketplace, mt.target_value, DATEADD(DAY, dg.day_offset, mt.month_start) AS day_date, DAY(mt.month_end) AS num_days_in_month FROM monthly_targets mt JOIN day_generator dg ON DATEADD(DAY, dg.day_offset, mt.month_start) <= mt.month_end ) SELECT day_date AS month, metric, Chain, marketplace, CASE WHEN upper(marketplace) ILIKE \'%TOTAL\' THEN TRIM(REPLACE(marketplace, \'TOTAL\', \'\')) ELSE marketplace END AS Final_marketplace, target_value / num_days_in_month AS Target_Numerator, NULL AS Target_Denominator FROM expanded_days t WHERE metric IS NOT NULL and day_date < current_date ORDER BY marketplace, metric, month ) select a.month_date as month_date, COALESCE(a.month_date, t.month)::DATE AS Month, COALESCE(a.metric, t.metric) AS metric, upper(COALESCE(channel,Chain)) as new_channel, upper(coalesce(a.Final_marketplace,t.Final_marketplace)) as Final_marketplace, coalesce(type,\'NR\') as type, upper(COALESCE(a.marketplace, t.marketplace)) AS marketplace, upper(COALESCE(Net_Realization, t.marketplace)) AS channel, a.Actual_Numerator::FLOAT AS Actual_Numerator, a.Actual_Denominator::FLOAT AS Actual_Denominator, a.tertiary as tertiary, t.Target_Numerator AS Target_Numerator, t.Target_Denominator::FLOAT AS Target_Denominator FROM Actuals a FULL OUTER JOIN Targets t ON a.month_date = t.month AND LOWER(a.metric) = LOWER(t.metric) and lower(Net_Realization) = lower(t.marketplace) and lower(channel) = lower(t.chain) ; create or replace table datalake_db.kaya.dwh_kaya_secondary_offtake_report as with base as ( select a.month_date ,a.material_group_code ,a.material_code ,case when lower(c.customer_name ) like \'%flipkart%\' then \'FLIPKART\' when lower(c.customer_name ) like \'%grofers%\' then \'BLINKIT\' when lower(c.customer_name ) like \'%innovative retail%\' then \'BIG BASKET\' when lower(c.customer_name ) like \'%kiranakart tech%\' then \'ZEPTO\' when lower(c.customer_name ) like \'%nykaa%\' then \'NYKAA\' when upper(c.customer_name ) like \'%RK WORLDINFOCOM%\' then \'AMAZON\' when upper(c.customer_name ) like \'%SCOOTSY LOGISTICS%\' then \'SWIGGY\' else upper(c.customer_name ) end as customer_name ,c.channel_name ,map.category ,fsm.Sub_Category ,fsm.product_title ,a.pri_actuals_vol_rum*b.turnover as secondary_value from datalake_db_shr.public.TRN_DWH_BPM_DIST_SKU_DAILY_PWBI a left join datalake_db_shr.public.TRN_DWH_SAP_INDEX_TURNOVER_MONTHWISE_PWBI b on a.index_wid=b.Row_wid left join datalake_db_shr.public.TRN_MST_CUSTOMER_PWBI c on a.customer_wid=c.row_wid left join ( select material_code,category from PRD_DB_SHR.PUBLIC.DWH_IND_ECOMM_OFFTAKE_DAILY qualify row_number() over(partition by lower(material_code) order by 1) =1 )map on lower(map.material_code) = lower(a.material_code) left join ( select * from datalake_db.kaya.Final_SKU_master qualify row_number() over(partition by trim(upper(marico_code)) order by 1) = 1 )fsm on upper(a.material_code) = upper(fsm.marico_code) where c.channel_name=\'E-Commerce\' and upper(material_group_code) in (\'KAYA_ML\',\'KAYA_GM\') ), Months as ( select last_day(dateadd(month,1,month_date)) Date, customer_name Channel, sum(ifnull(SECONDARY_VALUE,0)) month_INDEXBPM from Base group by 1,2 ) select bs.*, div0(ifnull(month_INDEXBPM,0),count(*) over(partition by last_day(bs.month_date), lower(bs.customer_name))) as Last_Month_SECONDARY_VALUE from Base bs left join Months ms on last_day(bs.month_date) = ms.date and lower(bs.customer_name) = lower(ms.Channel) ; Create or replace table datalake_db.kaya.dwh_kaya_primary_secondary_monthly_report as with offtake as ( select last_day(date) month ,upper(platform_name) platform_name ,material_code ,sum(ifnull(indexbpm,0)) indexbpm ,sum(shipped_unit) as shipped_unit from datalake_db.kaya.dwh_kaya_daily_offtake_report group by 1,2,3 ), secondary as ( select last_Day(month_date) as month ,upper(customer_name) channel_name ,material_code ,sum(ifnull(secondary_value,0))/100000 secondary_value from datalake_db.kaya.dwh_kaya_secondary_offtake_report group by 1,2,3 ) select coalesce(o.month,s.month) month, coalesce(upper(platform_name),upper(s.channel_name)) channel, coalesce(upper(o.material_code),upper(s.material_code)) material_code, o.indexbpm, s.secondary_value from offtake o full outer join secondary s on o.month = s.month and upper(platform_name) = upper(s.channel_name) and upper(o.material_code) = upper(s.material_code) ; create or replace table datalake_db.kaya.dwh_kaya_offtake_marketing_Data as with Base_Spends as ( select client_id, channel_id, \'AMAZON\' as Channel, country, campaign_id, campaign_name, sku_name, program_type, report_date, sum(impression)AS impression, sum(click) AS clicks, sum(orders) AS orders, sum(spend) AS spends, sum(sale) AS sales from DEV_DB_SHR.VENDOR.TRN_MEDIA_CAMPAIGN_DATA where channel_id in (1) and lower(record_type) = \'campaign\' group by 1,2,3,4,5,6,7,8,9 UNION ALL select client_id, channel_id, case when channel_id = 28 then \'MYNTRA\' when channel_id = 65 then \'SWIGGY\' when channel_id = 109 then \'ZEPTO\' when channel_id = 27 then \'BLINKIT\' end as Channel, country, campaign_id, campaign_name, sku_name, program_type, report_date, sum(impression)AS impression, sum(click) AS clicks, sum(orders) AS orders, sum(spend) AS spends, sum(sale) AS sales from DEV_DB_SHR.VENDOR.TRN_MEDIA_CAMPAIGN_DATA where channel_id in (27,65,109,28) AND lower(campaign_name) LIKE \'%kaya%\' and lower(record_type) = \'campaign\' group by 1,2,3,4,5,6,7,8,9 ), Month_Spends as ( select last_day(dateadd(month,1,report_date)) Date, Channel, sum(ifnull(spends,0)) month_spends from Base_Spends group by 1,2 ) select bs.*, div0(ifnull(month_spends,0),count(*) over(partition by last_day(bs.report_date), lower(bs.Channel))) as Last_Month_Spends from Base_Spends bs left join Month_Spends ms on last_day(bs.report_date) = date and lower(bs.Channel) = lower(ms.Channel) ;",
                    "transaction": true
